#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        1 <= k,
        k < list.len(), // strictly less: removing the last element is not allowed
    ensures
        new_list.len() == list.len() - 1,
        // Order-preserving removal of the 1-based k-th element:
        // for indices before k-1 (0-based), elements are unchanged
        forall|i: int|
            0 <= i < (k - 1) as int ==> new_list[i] == list[i],
        // for indices at/after k-1, new_list shifts left by 1 compared to list
        forall|i: int|
            (k - 1) as int <= i < new_list.len() as int ==> new_list[i] == list[i + 1],
{
    let n = list.len();
    let remove_idx = k - 1;

    let mut out: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == list.len(),
            n > 0,
            1 <= k,
            k < n,
            remove_idx == k - 1,
            i <= n,
            out.len() == if i <= remove_idx { i } else { i - 1 },

            // Elements copied so far (prefix of out) match the spec
            forall|j: int|
                0 <= j < out.len() as int
                ==> out[j] == list[if j < remove_idx as int { j } else { j + 1 }],
        decreases n - i
    {
        if i != remove_idx {
            out.push((*list)[i]);
        }
        i += 1;
    }

    // At loop end, i == n, so out.len() == n-1 (since remove_idx < n)
    assert(i == n);
    assert(out.len() == n - 1);

    out
}

} // verus!